class stringx;

extern "C" void *memmove(void *, const void *, unsigned int);
extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

template<class T>
class my_allocator
{
public:
  static T *allocate(unsigned int n)
  {
    return n ? (T *)arch_malloc(n * sizeof(T), __FILE__, 0) : 0;
  }

  static void deallocate(T *p, unsigned int)
  {
    if (p)
      arch_free(p);
  }
};

template<class T>
inline T *copy(const T *first, const T *last, T *result)
{
  memmove(result, first, sizeof(T) * (last - first));
  return result + (last - first);
}

template<class T>
inline T *uninitialized_copy(const T *first, const T *last, T *result)
{
  return copy(first, last, result);
}

template<class T>
inline void destroy(T *, T *)
{
}

template<class T, class Alloc>
class vector
{
protected:
  T *start_;
  T *finish_;
  T *end_of_storage_;

  T *allocate(unsigned int n) { return Alloc::allocate(n); }
  void deallocate(T *p, unsigned int n) { Alloc::deallocate(p, n); }

  template<class InputIterator>
  T *allocate_and_copy(unsigned int n, InputIterator first, InputIterator last)
  {
    T *result = allocate(n);
    uninitialized_copy(first, last, result);
    return result;
  }

public:
  typedef T *iterator;
  typedef const T *const_iterator;
  typedef unsigned int size_type;

  iterator begin() { return start_; }
  const_iterator begin() const { return start_; }
  iterator end() { return finish_; }
  const_iterator end() const { return finish_; }
  size_type size() const { return finish_ - start_; }
  size_type capacity() const { return end_of_storage_ - start_; }
  vector &operator=(const vector &x);
};

template<class T, class Alloc>
vector<T, Alloc> &vector<T, Alloc>::operator=(const vector<T, Alloc> &x)
{
  if (&x != this)
  {
    if (x.size() > capacity())
    {
      iterator tmp = allocate_and_copy(x.end() - x.begin(), x.begin(), x.end());
      destroy(start_, finish_);
      deallocate(start_, end_of_storage_ - start_);
      start_ = tmp;
      end_of_storage_ = start_ + (x.end() - x.begin());
    }
    else if (size() >= x.size())
    {
      iterator i = copy(x.begin(), x.end(), begin());
      destroy(i, finish_);
    }
    else
    {
      copy(x.begin(), x.begin() + size(), start_);
      uninitialized_copy(x.begin() + size(), x.end(), finish_);
    }
    finish_ = start_ + x.size();
  }
  return *this;
}

template vector<stringx *, my_allocator<stringx *> > &
vector<stringx *, my_allocator<stringx *> >::operator=(
  const vector<stringx *, my_allocator<stringx *> > &);
